def val_if_below_diag(r, c, special_r, special_c):
    ri, ci = r - 3, c - 4
    sr, sc = special_r - 3, special_c - 4

    # Check if (ri, ci) is BELOW diagonal r - c = special
    below = (ri - ci > sr - sc)  # row - col index is larger

