            elif (ri < 3 and ci >= 3) and (sr >= 3 and sc < 3):
                # TR quadrant gets 2s if special is in BL
                grid[ri][ci] = 2
            elif (ri >= 3 and ci < 3) and (sr < 3 and sc >= 3):
